fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    
    // If the length is 1, return a clone of the input
    if n == 1 {
        return a.clone();
    }
    
    // Create a new vector with the same length as the input
    let mut result = vec![0; n];
    
    // Set the first element of the result to the last element of the input
    result[0] = a[n - 1];
    
    // Copy the interior elements
    for i in 1..n - 1 {
        result[i] = a[i];
    }
    
    // Set the last element of the result to the first element of the input
    result[n - 1] = a[0];
    
    result
}